      "stem": "两位正整数的简单算术运算（只考虑整数运算），算术运算为： +，加法运算； -，减法运算； *，乘法运算； /，整除运算； %，取余运算。 算术表达式的格式为（运算符前后可能有空格）：运算数运算符运算数编写Fun 函数完成上述各个计算功能，输入输出均在主函数内例如输入32+64 那么输出96",
      "code": null,
